    "v7": "rate_code",
    "v9": "rate_index",
    "v10": "rate_entry",
    "v11": "rate_entry_index",
    "v12": "pkt_table_base",
    "v13": "he_params"
  },
  "struct_hints": [
    {
      "offset": 28,
      "meaning": "input descriptor word read into local v4"
    },
    {
      "offset": 48,
      "meaning": "input descriptor length/status field tested against 0x1C in an assert"
    },
    {
      "offset": 84,
      "meaning": "input descriptor word holding rate/MCS bits and HE flag bit 25"
    },
    {
      "offset": 34,
      "meaning": "rate-table entry index byte used to locate a packet table slot"
    },
    {
      "offset": 37,
      "meaning": "rate-table entry validity/configured byte"
    },
    {
      "offset": 38,
      "meaning": "rate-table entry 32-bit value copied into the TX descriptor"
    },
    {
      "offset": 42,
      "meaning": "rate-table entry 16-bit value copied into a MAC descriptor field"
    }
  ]
}
